create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role text not null check (role in ('student','svl','admin')), email text, created_at timestamptz default now());
create table if not exists public.classes (id bigint generated by default as identity primary key, name text not null, code text unique not null, created_at timestamptz default now());
create table if not exists public.class_members (id bigint generated by default as identity primary key, class_id bigint references public.classes(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, unique(class_id,user_id));
create table if not exists public.notes (id bigint generated by default as identity primary key, class_id bigint references public.classes(id) on delete cascade, title text not null, file_url text, uploaded_by uuid references public.profiles(id), created_at timestamptz default now());
create table if not exists public.notices (id bigint generated by default as identity primary key, class_id bigint references public.classes(id) on delete cascade, title text not null, body text not null, created_by uuid references public.profiles(id), created_at timestamptz default now());
create table if not exists public.timetable (id bigint generated by default as identity primary key, class_id bigint references public.classes(id) on delete cascade, subject text not null, day text not null, start_time time not null, end_time time not null, room text);
alter table public.profiles enable row level security;
alter table public.classes enable row level security;
alter table public.class_members enable row level security;
alter table public.notes enable row level security;
alter table public.notices enable row level security;
alter table public.timetable enable row level security;
create policy "profiles own read" on public.profiles for select using (auth.uid()=id);
create policy "classes authenticated read" on public.classes for select to authenticated using (true);
create policy "members own read" on public.class_members for select to authenticated using (user_id=auth.uid());
create policy "notes authenticated read" on public.notes for select to authenticated using (true);
create policy "notices authenticated read" on public.notices for select to authenticated using (true);
create policy "timetable authenticated read" on public.timetable for select to authenticated using (true);
